async function loadOpenNGC(){
  try{
    const url='https://raw.githubusercontent.com/mattiaverga/OpenNGC/master/database_files/NGC.csv';
    const response=await fetch(url,{mode:'cors',cache:'force-cache'});if(!response.ok)throw new Error('HTTP '+response.status);
    const csv=await response.text();const rows=parseCSV(csv);if(rows.length<1000)throw new Error('dataset incompleto');
    const headers=rows.shift().map(x=>x.trim());const ix=(...names)=>{for(const n of names){const i=headers.findIndex(h=>h.toLowerCase()===n.toLowerCase());if(i>=0)return i}return -1};
    const col={name:ix('Name'),type:ix('Type'),ra:ix('RA'),dec:ix('Dec'),const:ix('Const'),maj:ix('MajAx'),min:ix('MinAx'),pa:ix('PosAng'),mag:ix('V-Mag','B-Mag'),messier:ix('M'),common:ix('Common names'),ident:ix('Identifiers'),notes:ix('OpenNGC Notes')};
    const typeMap={G:'galassia',GPair:'galassia',GTrpl:'galassia',GGroup:'galassia',OCl:'ammasso',GCl:'ammasso',Assoc:'ammasso','Cl+N':'nebulosa',HII:'nebulosa',EmN:'nebulosa',RfN:'nebulosa',Neb:'nebulosa',DrkN:'nebulosa',PN:'planetaria',SNR:'resto'};
    const constNames={And:'Andromeda',Aqr:'Aquario',Aql:'Aquila',Aur:'Auriga',Boo:'Boote',Cam:'Giraffa',Cap:'Capricorno',Cas:'Cassiopea',Cep:'Cefeo',Cyg:'Cigno',Dra:'Drago',Gem:'Gemelli',Her:'Ercole',Lyr:'Lira',Mon:'Unicorno',Ori:'Orione',Per:'Perseo',Psc:'Pesci',Sge:'Freccia',Sgr:'Sagittario',Sct:'Scudo',Ser:'Serpente',Tau:'Toro',Tri:'Triangolo',UMa:'Orsa Maggiore',UMi:'Orsa Minore',Vir:'Vergine',Vul:'Volpetta',Com:'Chioma di Berenice',CVn:'Canes Venatici',CrB:'Corona Boreale',Lac:'Lucertola',Peg:'Pegaso',Pup:'Poppa',Vel:'Vela',Cen:'Centauro',Car:'Carena',Sco:'Scorpione',PsA:'Pesce Australe',Crt:'Coppa',Leo:'Leone',Lep:'Lepre',For:'Fornace',Eri:'Eridano',Del:'Delfino',Cnc:'Cancro',Lib:'Bilancia',Oph:'Ofiuco',Pav:'Pavone',Oct:'Ottante',Tuc:'Tucano',Ind:'Indiano',Col:'Colomba',Pic:'Pittore',Ret:'Reticolo',Hor:'Orologio',Dor:'Dorado',Cha:'Camaleonte',Mus:'Mosca',Ara:'Altare',Nor:'Squadra',Tel:'Telescopio',Crv:'Corvo',Hya:'Idra',CMa:'Cane Maggiore',CMi:'Cane Minore',Cae:'Bulino',Cir:'Compasso',Cru:'Croce del Sud',Phe:'Fenice',Ant:'Macchina Pneumatica',Mic:'Microscopio',Scl:'Scultore',Vol:'Pesce Volante',Men:'Mensa',TrA:'Triangolo Australe',Lup:'Lupo',Cyg:'Cigno',Equ:'Cavallino'};
    let add=[];for(const row of rows){const id=row[col.name]?.trim();if(!id||curatedIds.has(id))continue;const typ=typeMap[row[col.type]?.trim()];if(!typ)continue;const ra=parseRA(row[col.ra]),dec=parseDec(row[col.dec]),maj=parseFloat(row[col.maj]),mag=parseFloat(row[col.mag]);if(!Number.isFinite(ra)||!Number.isFinite(dec))continue;let name=row[col.common]?.trim().replace(/^"|"$/g,'');const names=name?name.split(/[,;]/).map(x=>x.trim()).filter(Boolean):[];let subtype=({galassia:'Galassia',ammasso:'Ammasso stellare',nebulosa:'Nebulosa',planetaria:'Nebulosa planetaria',resto:'Resto di supernova'})[typ];const constCode=row[col.const]?.trim();let note=row[col.notes]?.trim();add.push({id,name:names[0]||id,type:typ,subtype,ra,dec,size:Number.isFinite(maj)?maj:1,minor:Number.parseFloat(row[col.min])||null,mag:Number.isFinite(mag)?mag:null,const:constNames[constCode]||constCode||'—',season:seasonFor(ra,dec),moon:typ==='nebulosa'?'Bassa':'Media',filter:typ==='nebulosa'?'Ha · O III':'Nessuno',hours:typ==='resto'?12:typ==='nebulosa'?6:5,story:`${names.join(', ')||id} è un oggetto del catalogo NGC/IC. La scheda include coordinate J2000, classe e dimensione angolare dal database OpenNGC.`,culture:`Registrato come ${id}${row[col.messier]?.trim()?` e noto anche come Messier ${row[col.messier].trim()}`:''}. ${note||'La storia osservativa e il nome comune variano da oggetto a oggetto.'}`,science:`Classificazione catalografica: ${subtype.toLowerCase()}. L’estensione riportata è l’asse maggiore, in minuti d’arco; la magnitudine è ${Number.isFinite(mag)?mag.toFixed(1):'non disponibile'} nel filtro V/B secondo i dati OpenNGC.`,color:typ==='galassia'?'galassia':typ==='ammasso'?'ammasso':typ==='planetaria'?'planetaria':typ==='resto'?'resto':'color',source:'OpenNGC CC BY-SA 4.0'});}
    catalog.push(...add);add.forEach(o=>curatedIds.add(o.id));catalogLoaded=true;
    if(page==='catalog')render();else {const t=$('#collection-count');if(t)t.title=`${catalog.length} oggetti disponibili`}
  }catch(err){console.warn('OpenNGC non disponibile; uso catalogo curato locale.',err)}
}
function parseCSV(text){let out=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++}else if(c==='"')quoted=false;else field+=c}else if(c==='"')quoted=true;else if(c===','){row.push(field);field=''}else if(c==='\n'){row.push(field.replace(/\r$/,''));out.push(row);row=[];field=''}else field+=c}if(field||row.length){row.push(field);out.push(row)}return out}
function parseRA(s){if(!s)return NaN;const a=s.trim().split(':').map(Number);return a.length===3?(a[0]+a[1]/60+a[2]/3600)*15:Number(s)}
function parseDec(s){if(!s)return NaN;const a=s.trim().split(':');if(a.length===3){let sign=a[0].startsWith('-')?-1:1;return sign*(Math.abs(parseFloat(a[0]))+Number(a[1])/60+Number(a[2])/3600)}return Number(s)}
function seasonFor(ra,dec){const months=((ra/30+2)%12)+1;let start=Math.round(months-1);return [((start+10)%12)+1,((start+2)%12)+1]}

const demoGear=[{id:'gear-telescope',kind:'Telescope',name:'Tecnosky quadrupletto APO 70-350 f/5',aperture:70,focal:350},{id:'gear-filter',kind:'Filter',name:'Optolong L-eNhance 1.25"',note:'Dual-band Ha + O III'}];
const defaultSite={id:'site-home',name:'Sito principale',lat:45.4642,lon:9.19,elev:null,bortle:null,sqm:null};
let state=loadState(),page='home',activeFilters={type:'Tutti',season:'Tutti',sort:'fits'},weatherCache=null,catalogPage=1,catalogLoaded=false;
function loadState(){try{let s=JSON.parse(localStorage.getItem(STORE));return {...{gear:demoGear,sites:[defaultSite],projects:[],collection:[],activeSite:defaultSite.id},...s}}catch{return {gear:demoGear,sites:[defaultSite],projects:[],collection:[],activeSite:defaultSite.id}}}
function save(){localStorage.setItem(STORE,JSON.stringify(state));updateCounts()}
function updateCounts(){$('#collection-count').textContent=state.collection.length;$('#project-count').textContent=state.projects.length;$('#active-site-short').textContent=(state.sites.find(s=>s.id===state.activeSite)?.name||'Sito principale').slice(0,18)}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function rad(d){return d*Math.PI/180}function deg(d){return d*180/Math.PI}
function dateNow(){return new Date()}
function dayOfYear(d){return Math.floor((Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())-Date.UTC(d.getFullYear(),0,0))/86400000)}
function sunRaDec(date){const n=dayOfYear(date),L=(280.46+.9856474*n)%360,g=rad((357.528+.9856003*n)%360),lambda=rad(L+1.915*Math.sin(g)+.02*Math.sin(2*g)),eps=rad(23.439-.0000004*n);return {ra:(deg(Math.atan2(Math.cos(eps)*Math.sin(lambda),Math.cos(lambda)))+360)%360,dec:deg(Math.asin(Math.sin(eps)*Math.sin(lambda)))}}
function lst(date,lon){const jd=date.getTime()/86400000+2440587.5,T=(jd-2451545)/36525;let gmst=280.46061837+360.98564736629*(jd-2451545)+.000387933*T*T-T*T*T/38710000;return ((gmst+lon)%360+360)%360}
function altAz(ra,dec,lat,lon,date){const H=rad(((lst(date,lon)-ra+540)%360)-180),p=rad(lat),d=rad(dec);const alt=Math.asin(Math.sin(p)*Math.sin(d)+Math.cos(p)*Math.cos(d)*Math.cos(H));const az=Math.atan2(-Math.sin(H)*Math.cos(d),Math.sin(d)*Math.cos(p)-Math.cos(d)*Math.sin(p)*Math.cos(H));return {alt:deg(alt),az:(deg(az)+360)%360}}
function peakAlt(obj,site){return 90-Math.abs(site.lat-obj.dec)}
function monthName(n){return ['gen','feb','mar','apr','mag','giu','lug','ago','set','ott','nov','dic'][((n%12)+12)%12]}
function isSeason(obj,date=new Date()){let m=date.getMonth()+1;return obj.season[0]<=obj.season[1]?m>=obj.season[0]&&m<=obj.season[1]:m>=obj.season[0]||m<=obj.season[1]}
function fovData(){const t=state.gear.find(x=>x.kind==='Telescope'),c=state.gear.find(x=>x.kind==='Camera');if(!t||!c||!c.width||!c.height)return null;const f=t.focal*(t.factor||1),w=2*deg(Math.atan(c.width/(2*f))),h=2*deg(Math.atan(c.height/(2*f))),diag=Math.hypot(w,h)*60,scale=c.pixel?206.265*c.pixel/f:null;return {w,h,diag,scale,f}}
function suitability(obj){let f=fovData();if(!f)return 'setup incompleto';let objSize=obj.size; if(objSize>=f.w*60*.55&&objSize>=f.h*60*.55)return 'campo adatto';if(objSize<Math.min(f.w,f.h)*60*.12)return 'dettaglio / mosaico';return 'composizione';}
function fitScore(obj){let site=state.sites.find(x=>x.id===state.activeSite)||defaultSite;let alt=peakAlt(obj,site);let fits=suitability(obj);return (isSeason(obj)?35:5)+Math.min(alt,80)*.3+(fits==='campo adatto'?25:fits==='composizione'?15:5)+(obj.mag<8?10:0)}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2500)}
function go(p){page=p;$$('.rail-nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));const n={home:'PANORAMICA',catalog:'ATLANTE',projects:'PROGETTI',gear:'SETUP',sites:'LOCALITÀ',calendar:'CALENDARIO'};$('#page-name').textContent=n[p]||p.toUpperCase();$('.rail').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'})}
function render(){updateCounts();const views={home:renderHome,catalog:renderCatalog,gear:renderGear,sites:renderSites,projects:renderProjects,calendar:renderCalendar};$('#view').innerHTML=(views[page]||renderHome)();$('#view').classList.remove('fade-in');void $('#view').offsetWidth;$('#view').classList.add('fade-in');bindPage();}
function header(no,title,desc,action=''){return `<div class="page-title-row"><div><p class="eyebrow"><span>${no}</span> OURSKY / ${page.toUpperCase()}</p><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function renderHome(){const site=state.sites.find(s=>s.id===state.activeSite)||defaultSite;const featured=[...catalog].filter(o=>isSeason(o)&&peakAlt(o,site)>25).sort((a,b)=>fitScore(b)-fitScore(a)).slice(0,4);const f=fovData();let p=state.projects[0];return `${header('01','Il cielo, <em>per te.</em>','Scopri cosa fotografare dalla tua posizione, con il setup che hai e nelle notti che hai a disposizione.')}
<div class="hero-grid"><section class="card hero-card"><div><p class="eyebrow"><span>IL TUO CIELO · ${new Date().toLocaleDateString('it-IT',{day:'2-digit',month:'long'})}</span></p><h1>Una notte buona<br>inizia da <em>un’idea.</em></h1><p>Oggetti osservabili, campo reale, luna e meteo: il prossimo soggetto è più vicino di quanto pensi.</p></div><div class="hero-bottom"><button class="button" data-go="catalog">Esplora i soggetti <span>↗</span></button><span class="hero-index">${site.lat.toFixed(2)}° N / ${site.lon.toFixed(2)}° E</span></div></section><section class="card sky-card"><div class="coord">ATLANTE LOCALE · EQUATORE CELESTE</div><div class="sky-object"></div><span class="cross">✳</span><div><div class="sky-caption">${featured[0]?.name||'Il cielo stanotte'}</div><div class="sky-sub">${featured[0]?.const||'SOGGETTI SELEZIONATI PER IL TUO SITO'}</div></div></section></div>
<div class="stat-strip"><div class="stat"><label>IN STAGIONE · DAL TUO SITO</label><strong>${catalog.filter(o=>isSeason(o)&&peakAlt(o,site)>20).length}</strong><small>soggetti in catalogo</small></div><div class="stat"><label>CAMPO DI RIPRESA</label><strong>${f?f.w.toFixed(2)+'°':'—'}</strong><small>${f?`× ${f.h.toFixed(2)}°`:'aggiungi una camera'}</small></div><div class="stat"><label>SCALA IMMAGINE</label><strong>${f?.scale?f.scale.toFixed(2):'—'}</strong><small>${f?.scale?'″/pixel':'pixel camera da configurare'}</small></div><div class="stat"><label>PROGETTI ATTIVI</label><strong>${state.projects.length}</strong><small>${p?esc(p.name):'inizia a pianificare'}</small></div></div>
<div class="dash-lower"><section class="card"><div class="card-head"><h2>Da esplorare questa stagione</h2><button class="text-button" data-go="catalog">Apri atlante ↗</button></div>${featured.map(o=>`<div class="target-row" data-detail="${o.id}"><span class="target-thumb"></span><div><strong>${esc(o.name)}</strong><small>${o.id} · ${esc(o.const)} · ${o.type}</small></div><aside><span class="metric">${peakAlt(o,site).toFixed(0)}°</span><small>culmina</small></aside></div>`).join('')||'<div class="empty">Completa la località per vedere i soggetti del tuo cielo.</div>'}</section><section class="card"><div class="card-head"><h2>La prossima sessione</h2><button class="text-button" data-go="projects">Tutti i progetti ↗</button></div>${p?`<div class="label-tag">PROGETTO · ${esc(p.target||'SOGGETTO DA SCEGLIERE')}</div><h3 style="font:400 25px var(--serif);margin:12px 0 5px">${esc(p.name)}</h3><p style="font-size:10px;color:#85877f">${esc(p.siteName||site.name)} · ${esc(p.setupName||'Setup da definire')}</p><div class="progress" style="margin:17px 0 6px"><i style="width:${p.progress||22}%"></i></div><span class="label-tag">${p.progress||22}% · PREPARAZIONE</span><div style="margin-top:15px"><button class="button small" data-project="${p.id}">Apri progetto ↗</button></div>`:`<div class="empty">I tuoi obiettivi fotografici appariranno qui, insieme alle prossime finestre utili.</div><button class="button small" data-action="new-project">Crea un progetto</button>`}</section></div>
<div class="grid two-col" style="margin-top:13px"><section class="card"><div class="card-head"><h2>Osservatorio</h2><span>${esc(site.name)}</span></div><div id="weather-snippet"><div class="loading">Meteo locale · aggiorna...</div></div><div style="display:flex;gap:8px;margin-top:12px"><button class="button light small" data-go="sites">Località e cielo</button><button class="button light small" data-go="calendar">Fasi lunari e calendario</button></div></section><section class="card"><div class="card-head"><h2>La tua collezione</h2><span>${state.collection.length} soggetti esplorati</span></div>${state.collection.length?state.collection.slice(-3).reverse().map(id=>{const o=catalog.find(x=>x.id===id);return o?`<div class="activity"><i>✳</i><span>${esc(o.name)} · aggiunto all’atlante</span></div>`:''}).join(''):'<div class="empty">Salva i soggetti che ti incuriosiscono.<br>La tua mappa del cielo si riempirà un oggetto alla volta.</div>'}<button class="text-button" data-go="catalog">Continua a scoprire ↗</button></section></div>`}
function renderCatalog(){const site=state.sites.find(s=>s.id===state.activeSite)||defaultSite;let list=[...catalog];if(activeFilters.type!=='Tutti')list=list.filter(o=>o.type===activeFilters.type);if(activeFilters.season==='Stagione')list=list.filter(o=>isSeason(o));if(activeFilters.season==='Adatti al setup')list=list.filter(o=>suitability(o)!=='setup incompleto'&&suitability(o)!=='dettaglio / mosaico');if(activeFilters.sort==='fits')list.sort((a,b)=>fitScore(b)-fitScore(a));if(activeFilters.sort==='size')list.sort((a,b)=>b.size-a.size);if(activeFilters.sort==='mag')list.sort((a,b)=>a.mag-b.mag);return `${header('02','Atlante del cielo','Soggetti Messier, NGC, IC e Sharpless: filtra per stagione, campo reale e tipo. Apri una scheda per dati, scienza e storia.')}
<div class="toolbar"><input class="search" id="catalog-search" placeholder="Cerca per nome, catalogo, costellazione…" aria-label="Cerca soggetti"><select class="select" id="type-filter"><option>Tutti</option><option value="nebulosa">Nebulose</option><option value="galassia">Galassie</option><option value="ammasso">Ammassi</option><option value="planetaria">Planetarie</option><option value="resto">Resti di supernova</option></select><select class="select" id="season-filter"><option value="Tutti">Tutti i periodi</option><option value="Stagione">In stagione ora</option><option value="Adatti al setup">Adatti al setup</option></select><select class="select" id="sort-filter"><option value="fits">Consigliati per me</option><option value="size">Più estesi</option><option value="mag">Più luminosi</option></select><span class="filter-count" id="filter-count">${list.length} soggetti</span></div><div class="notice" style="margin-bottom:13px">Il catalogo OpenNGC viene caricato quando la rete è disponibile; i 33 soggetti curati restano consultabili anche offline. OpenNGC è CC BY-SA 4.0. Le misure e magnitudini sono riferimenti catalografici; la visibilità reale dipende da cielo, altezza, ottica e integrazione. I filtri e il punteggio sono indicativi.</div><div class="target-grid" id="target-grid">${targetCards(list.slice(0,42),site)}</div><div id="catalog-more" style="text-align:center;padding:20px">${list.length>42?`<button class="button light" id="load-more">Mostra altri 42 · ${list.length-42} ancora</button>`:''}</div>`}
function targetCards(list,site){return list.map(o=>`<article class="target-card" data-detail="${o.id}"><div class="target-art" data-type="${o.color}"><span class="art-id">${o.id}</span></div><div class="target-card-body"><h3>${esc(o.name)}</h3><p>${esc(o.subtype)} · ${esc(o.const)}</p><div class="target-meta"><span>${o.size>=60?(o.size/60).toFixed(1)+'°':o.size+'′'}</span><span>mag ${o.mag}</span><span>${suitability(o)}</span></div><div class="target-card-foot"><span>culmina ~${peakAlt(o,site).toFixed(0)}°</span><b>${isSeason(o)?'IN STAGIONE':'ALTRA STAGIONE'}</b></div></div></article>`).join('')||'<div class="empty">Nessun soggetto corrisponde a questa ricerca.</div>'}
function renderGear(){const f=fovData();const camera=state.gear.find(x=>x.kind==='Camera');return `${header('03','Il tuo setup','Aggiungi componenti reali o personalizzati. OurSky calcola campo, diagonale e campionamento dai dati ottici e dal sensore.','<button class="button" data-action="add-gear">+ Aggiungi componente</button>')}<div class="grid two-col"><section class="card"><div class="card-head"><h2>Componenti</h2><span>${state.gear.length} elementi</span></div><div class="gear-list">${state.gear.map(g=>`<div class="gear-item"><div class="gear-icon">${g.kind==='Telescope'?'◉':g.kind==='Camera'?'▣':g.kind==='Filter'?'◌':'⌘'}</div><div><h3>${esc(g.name)}</h3><p>${gearSummary(g)}</p></div><button class="remove" data-remove-gear="${g.id}" title="Rimuovi">×</button></div>`).join('')||'<div class="empty">Aggiungi un telescopio, una camera e i filtri che usi.</div>'}</div><div class="notice" style="margin-top:14px">Lunghezze focali, dimensioni sensore e passo pixel devono corrispondere alla scheda del produttore. I campi mancanti restano da inserire: niente specifiche stimate.</div></section><section class="card"><div class="card-head"><h2>Campo risultante</h2><span>sensore + ottica</span></div>${f?`<div class="sensor-box"><svg viewBox="0 0 300 200" preserveAspectRatio="none"><rect x="1" y="1" width="298" height="198" fill="none" stroke="#6379b3" stroke-dasharray="4 4"/><line x1="150" y1="1" x2="150" y2="199" stroke="#6379b355"/><line x1="1" y1="100" x2="299" y2="100" stroke="#6379b355"/><line x1="1" y1="1" x2="299" y2="199" stroke="#6379b3"/></svg><span class="sensor-caption">${f.w.toFixed(2)}° × ${f.h.toFixed(2)}° · diagonale ${f.diag.toFixed(0)}′</span></div><div class="setup-preview"><div><span>CAMPO ORIZZONTALE</span><strong>${f.w.toFixed(2)}°</strong></div><div><span>CAMPO VERTICALE</span><strong>${f.h.toFixed(2)}°</strong></div><div><span>DIAGONALE</span><strong>${f.diag.toFixed(1)}′</strong></div><div><span>CAMPIONAMENTO</span><strong>${f.scale?f.scale.toFixed(2)+'″/px':'—'}</strong></div></div><p style="font-size:9px;color:#888">${f.scale?`Scala calcolata: 206,265 × ${camera.pixel} μm / ${f.f} mm.`:'Inserisci il pixel pitch per il campionamento.'}</p>`:`<div class="empty">Per calcolare il campo servono telescopio e camera con larghezza/altezza del sensore. Aggiungi i dati esatti dalla scheda tecnica.</div><button class="button small" data-action="add-gear">Configura camera</button>`}</section></div><section class="card" style="margin-top:13px"><div class="card-head"><h2>Equilibrio e checklist</h2><span>prima di partire</span></div><div class="grid three-col"><label class="switch-row"><span>Montatura e contrappesi</span><input type="checkbox" data-check="mount"></label><label class="switch-row"><span>Alimentazione e batterie</span><input type="checkbox" data-check="power"></label><label class="switch-row"><span>Fascia anticondensa</span><input type="checkbox" data-check="dew"></label><label class="switch-row"><span>Cavi e hub USB</span><input type="checkbox" data-check="cables"></label><label class="switch-row"><span>Bahtinov / messa a fuoco</span><input type="checkbox" data-check="focus"></label><label class="switch-row"><span>Flat panel / flat</span><input type="checkbox" data-check="flats"></label></div></section>`}
function gearSummary(g){if(g.kind==='Telescope')return `${g.aperture||'—'} mm · ${g.focal||'—'} mm · f/${g.focal?(g.focal/(g.aperture||1)).toFixed(1):'—'}`;if(g.kind==='Camera')return `${g.width||'?'} × ${g.height||'?'} mm · ${g.pixel?g.pixel+' μm':'pixel non inserito'}`;return g.note||g.kind}
function renderSites(){const site=state.sites.find(s=>s.id===state.activeSite)||defaultSite;return `${header('04','Località','Salva i tuoi siti, verifica le coordinate e confronta meteo, altitudine e qualità del cielo.','<button class="button" data-action="add-site">+ Aggiungi località</button>')}<div class="grid two-col"><section class="card"><div class="card-head"><h2>Luogo attivo</h2><select class="select" id="site-select">${state.sites.map(s=>`<option value="${s.id}" ${s.id===site.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="location-hero"><div><div class="label-tag">COORDINATE · ${site.lat.toFixed(4)}°, ${site.lon.toFixed(4)}°</div><div style="font:400 25px var(--serif);margin-top:8px">${esc(site.name)}</div><div class="weather-detail"><span>ALT. ${site.elev?site.elev+' m':'non rilevata'}</span><span>BORTLE ${site.bortle||'—'}</span><span>SQM ${site.sqm||'—'}</span></div></div><a class="map-link" href="https://www.openstreetmap.org/?mlat=${site.lat}&mlon=${site.lon}#map=10/${site.lat}/${site.lon}" target="_blank" rel="noreferrer">Apri mappa ↗</a></div><div style="margin-top:15px" id="weather-full"><div class="loading">Caricamento previsioni Open-Meteo…</div></div><div style="display:flex;gap:8px;margin-top:12px"><a class="button light small" href="https://www.lightpollutionmap.info/#zoom=8&lat=${site.lat}&lon=${site.lon}" target="_blank" rel="noreferrer">Mappa inquinamento luminoso ↗</a><button class="button light small" data-action="refresh-weather">Aggiorna meteo</button></div></section><section class="card"><div class="card-head"><h2>Orizzonte e cielo</h2><span>strumenti di località</span></div><div class="grid three-col"><div class="stat"><label>LATITUDINE</label><strong>${site.lat.toFixed(2)}°</strong></div><div class="stat"><label>LONGITUDINE</label><strong>${site.lon.toFixed(2)}°</strong></div><div class="stat"><label>EMISFERO</label><strong>${site.lat>=0?'N':'S'}</strong></div></div><div class="notice" style="margin-top:14px">Classe Bortle e SQM non sono disponibili da un servizio pubblico gratuito uniforme senza chiave/API specifica. La mappa Light Pollution Map si apre centrata sul sito; inserisci la misura SQM/Bortle locale per salvarla. Elevazione e profilo dell’orizzonte possono essere arricchiti con dati DEM in una prossima integrazione.</div><div class="grid two-col" style="margin-top:14px"><div class="field"><label>Classe Bortle (1–9)</label><select id="bortle-edit"><option value="">Non indicata</option>${Array.from({length:9},(_,i)=>`<option value="${i+1}" ${site.bortle==i+1?'selected':''}>${i+1}</option>`).join('')}</select></div><div class="field"><label>Misura SQM (mag/arcsec²)</label><input id="sqm-edit" type="number" step="0.1" value="${site.sqm||''}" placeholder="es. 21.3"></div></div><div class="form-foot"><button class="button small" data-action="save-sky">Salva qualità cielo</button></div></section></div><section class="card" style="margin-top:13px"><div class="card-head"><h2>Le tue località</h2><span>casa · montagna · trasferta</span></div><div class="grid three-col">${state.sites.map(s=>`<div class="gear-item"><div class="gear-icon">⌖</div><div><h3>${esc(s.name)}</h3><p>${s.lat.toFixed(3)}, ${s.lon.toFixed(3)} · Bortle ${s.bortle||'—'}</p></div>${s.id!==defaultSite.id?`<button class="remove" data-remove-site="${s.id}">×</button>`:''}</div>`).join('')}</div></section>`}
function renderProjects(){return `${header('05','Progetti','Trasforma un soggetto in un piano: setup, sito, condizioni minime e finestre possibili.','<button class="button" data-action="new-project">+ Nuovo progetto</button>')}<div class="grid two-col" style="margin-bottom:14px"><section class="card"><div class="card-head"><h2>Pianificazione sessione</h2><span>progetti salvati</span></div><p style="font-size:11px;color:#7b7d75;line-height:1.6;margin:0">Ogni progetto conserva soggetto, attrezzatura, luogo, obiettivo di integrazione e limiti meteo. Le prossime finestre combinano stagione, altezza culminante e fase lunare; il meteo diventa attendibile solo nel breve periodo.</p></section><section class="card"><div class="card-head"><h2>Passi di una sessione</h2><span>checklist</span></div><div class="activity"><i>01</i><span>Soggetto e composizione nel tuo campo</span></div><div class="activity"><i>02</i><span>Notte, luna e meteo accettabile</span></div><div class="activity"><i>03</i><span>Gear, alimentazione e acquisizione</span></div></section></div>${state.projects.length?state.projects.map(p=>`<article class="project-card" data-project="${p.id}"><i class="project-color"></i><div class="project-main"><h3>${esc(p.name)}</h3><p>${esc(p.target||'Soggetto da definire')} · ${esc(p.setupName||'setup da scegliere')} · ${esc(p.siteName||'località')}</p><div class="target-meta"><span>obiettivo ${p.hours||4} h</span><span>luna max ${p.moon||35}%</span><span>altezza min ${p.alt||30}°</span></div></div><aside>APRI<br><b style="font:20px var(--serif)">↗</b></aside></article>`).join(''):'<section class="card empty">Non hai ancora progetti. Parti da un soggetto nell’atlante o crea un obiettivo annuale.</section>'}<div class="grid two-col" style="margin-top:16px"><section class="card"><div class="card-head"><h2>Checklist sessione</h2><button class="text-button" data-action="reset-check">Azzera</button></div>${[['Batterie cariche','battery'],['Contrappesi e barra','weight'],['Alimentazione / cavi','cable'],['Fascia anticondensa','dew2'],['Focheggiatore / maschera','focus2'],['Piano sequenza acquisizione','sequence']].map(([l,k])=>`<label class="switch-row"><span>${l}</span><input type="checkbox" data-check="${k}"></label>`).join('')}</section><section class="card"><div class="card-head"><h2>Strumenti sessione</h2><span>posizione attiva</span></div><div class="activity"><i>◷</i><span>Calendario lunare e finestre notte</span><button class="text-button" data-go="calendar">Apri</button></div><div class="activity"><i>☁</i><span>Previsioni 7–16 giorni da Open-Meteo</span><button class="text-button" data-go="sites">Apri</button></div><div class="activity"><i>⌖</i><span>Coordinate per puntamento e scheda target</span></div></section></div>`}
function renderCalendar(){let d=new Date();let y=d.getFullYear(),m=d.getMonth();let first=new Date(y,m,1),start=(first.getDay()+6)%7;let days=new Date(y,m+1,0).getDate();const moons=['🌑','🌒','🌓','🌔','🌕','🌖','🌗','🌘'];return `${header('06','Calendario','Fasi lunari calcolate localmente, soggetti in stagione e notti disponibili per i tuoi progetti.','<div class="inline-actions"><button class="button light" id="prev-month">←</button><button class="button light" id="next-month">→</button></div>')}<section class="card"><div class="card-head"><h2 id="calendar-title">${new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric'}).format(d)}</h2><span>ORA LOCALE · ${esc((state.sites.find(s=>s.id===state.activeSite)||defaultSite).name)}</span></div><div class="calendar-grid">${['LUN','MAR','MER','GIO','VEN','SAB','DOM'].map(w=>`<div class="day" style="min-height:26px;background:#eeece5;font-size:8px;letter-spacing:.1em">${w}</div>`).join('')}${Array.from({length:42},(_,i)=>{let n=i-start+1,actual=n>0&&n<=days,dt=new Date(y,m,n),illum=moonIllum(dt),phase=moonEmoji(dt),obs=catalog.filter(o=>isSeason(o,dt)).sort((a,b)=>b.size-a.size)[0];return `<div class="day ${actual?'':'muted'} ${actual&&n===d.getDate()?'today':''}">${actual?n:''}<span class="moon">${actual?phase:''}</span>${actual&&obs&&n%4===0?`<span class="event-dot">${obs.id} · ${esc(obs.name)}</span>`:''}${actual&&n===15?`<span class="event-dot" style="background:#f4e6bf;color:#775d14">Luna ${illum}%</span>`:''}</div>`}).join('')}</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:14px"><span class="chip">🌑 Luna nuova · banda stretta e galassie deboli</span><span class="chip">🌕 Luna piena · planetarie e banda stretta selettiva</span><span class="chip">● Fasi stimate con algoritmo lunare</span></div></section><div class="grid two-col" style="margin-top:13px"><section class="card"><div class="card-head"><h2>Finestre lunari prossime</h2><span>prossimi 30 giorni</span></div>${nextMoonEvents().map(x=>`<div class="activity"><i>${x.icon}</i><span>${x.label}</span><b style="margin-left:auto">${x.date}</b></div>`).join('')}</section><section class="card"><div class="card-head"><h2>In stagione ora</h2><span>${catalog.filter(o=>isSeason(o)).length} candidati</span></div>${catalog.filter(o=>isSeason(o)).sort((a,b)=>b.size-a.size).slice(0,4).map(o=>`<div class="target-row" data-detail="${o.id}"><span class="target-thumb"></span><div><strong>${esc(o.name)}</strong><small>${o.id} · ${esc(o.const)}</small></div><aside>${o.size>=60?(o.size/60).toFixed(1)+'°':o.size+'′'}</aside></div>`).join('')}</section></div>`}
function moonIllum(d){const syn=29.530588853,ref=Date.UTC(2000,0,6,18,14);let age=((d.getTime()-ref)/86400000%syn+syn)%syn;return Math.round((1-Math.cos(2*Math.PI*age/syn))/2*100)}
function moonEmoji(d){let syn=29.530588853,ref=Date.UTC(2000,0,6,18,14),age=((d.getTime()-ref)/86400000%syn+syn)%syn;return ['🌑','🌒','🌓','🌔','🌕','🌖','🌗','🌘'][Math.round(age/syn*8)%8]}
function nextMoonEvents(){let d=new Date(),arr=[];for(let i=0;i<35;i++){let x=new Date(d.getFullYear(),d.getMonth(),d.getDate()+i),illum=moonIllum(x);if(illum<3||illum>97)arr.push({icon:illum<3?'🌑':'🌕',label:illum<3?'Luna nuova · finestra buia':'Luna piena · soggetti luminosi',date:x.toLocaleDateString('it-IT',{day:'numeric',month:'short'})})}return arr.slice(0,4)}
function bindDetailClicks(){$$('[data-detail]').forEach(el=>el.onclick=()=>openDetail(el.dataset.detail))}
function bindPage(){ $$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('[data-detail]').forEach(el=>el.onclick=()=>openDetail(el.dataset.detail));$$('[data-action]').forEach(b=>b.onclick=()=>actions(b.dataset.action));$$('[data-remove-gear]').forEach(b=>b.onclick=e=>{e.stopPropagation();state.gear=state.gear.filter(g=>g.id!==b.dataset.removeGear);save();render()});$$('[data-remove-site]').forEach(b=>b.onclick=e=>{e.stopPropagation();state.sites=state.sites.filter(s=>s.id!==b.dataset.removeSite);if(state.activeSite===b.dataset.removeSite)state.activeSite=state.sites[0]?.id;save();render()});$$('[data-check]').forEach(i=>{i.checked=!!localStorage.getItem('check-'+i.dataset.check);i.onchange=()=>localStorage.setItem('check-'+i.dataset.check,i.checked?'1':'')});$('#site-select')?.addEventListener('change',e=>{state.activeSite=e.target.value;save();render()});$('#bortle-edit')?.addEventListener('change',()=>saveSky());$('#sqm-edit')?.addEventListener('change',()=>saveSky());$('#load-more')?.addEventListener('click',()=>loadMoreCatalog());$('#catalog-search')?.addEventListener('input',filterCatalog);$('#type-filter')?.addEventListener('change',e=>{activeFilters.type=e.target.value;filterCatalog()});$('#season-filter')?.addEventListener('change',e=>{activeFilters.season=e.target.value;filterCatalog()});$('#sort-filter')?.addEventListener('change',e=>{activeFilters.sort=e.target.value;filterCatalog()});$('#prev-month')?.addEventListener('click',()=>shiftMonth(-1));$('#next-month')?.addEventListener('click',()=>shiftMonth(1));$$('[data-project]').forEach(el=>el.onclick=()=>openProject(el.dataset.project));if(page==='home'||page==='sites')loadWeather();}
function loadMoreCatalog(){const list=window._filteredCatalog||catalog,site=state.sites.find(x=>x.id===state.activeSite)||defaultSite;catalogPage++;const start=catalogPage*42;$('#target-grid').insertAdjacentHTML('beforeend',targetCards(list.slice(start,start+42),site));const remain=list.length-(start+42);$('#catalog-more').innerHTML=remain>0?`<button class="button light" id="load-more">Mostra altri 42 · ${remain} ancora</button>`:'';$('#load-more')?.addEventListener('click',loadMoreCatalog);bindDetailClicks()}
function filterCatalog(){catalogPage=0;let q=($('#catalog-search')?.value||'').toLowerCase(),site=state.sites.find(s=>s.id===state.activeSite)||defaultSite;let list=[...catalog].filter(o=>(!q||[o.id,o.name,o.const,o.subtype].join(' ').toLowerCase().includes(q))&&(activeFilters.type==='Tutti'||o.type===activeFilters.type)&&(activeFilters.season==='Tutti'||activeFilters.season==='Stagione'&&isSeason(o)||activeFilters.season==='Adatti al setup'&&suitability(o)!=='setup incompleto'&&suitability(o)!=='dettaglio / mosaico'));if(activeFilters.sort==='fits')list.sort((a,b)=>fitScore(b)-fitScore(a));if(activeFilters.sort==='size')list.sort((a,b)=>b.size-a.size);if(activeFilters.sort==='mag')list.sort((a,b)=>a.mag-b.mag);window._filteredCatalog=list;$('#target-grid').innerHTML=targetCards(list.slice(0,42),site);$('#filter-count').textContent=`${list.length} soggetti`;$('#catalog-more').innerHTML=list.length>42?`<button class="button light" id="load-more">Mostra altri 42 · ${list.length-Math.min(list.length,42)} ancora</button>`:'';$('#load-more')?.addEventListener('click',loadMoreCatalog);$$('[data-detail]').forEach(el=>el.onclick=()=>openDetail(el.dataset.detail))}
function openDetail(id){const o=catalog.find(x=>x.id===id);if(!o)return;const site=state.sites.find(s=>s.id===state.activeSite)||defaultSite,alt=peakAlt(o,site),f=fovData(),saved=state.collection.includes(id);$('#detail-dialog').innerHTML=`<div class="detail-top"><button class="close-detail" data-close>×</button><div class="label-tag" style="color:#c5c9d3">${o.id} · ${esc(o.subtype)}</div><h2>${esc(o.name)}</h2><p>${esc(o.const)} · ${o.ra.toFixed(4)}° RA · ${o.dec>=0?'+':''}${o.dec.toFixed(4)}° Dec</p></div><div class="detail-content"><div class="facts"><div class="fact"><span>DIMENSIONE</span><b>${o.size>=60?(o.size/60).toFixed(2)+'°':o.size+'′'}</b></div><div class="fact"><span>MAGNITUDINE</span><b>${o.mag}</b></div><div class="fact"><span>TIPO</span><b>${esc(o.type)}</b></div><div class="fact"><span>CULMINAZIONE DAL SITO</span><b>${alt.toFixed(0)}°</b></div></div><div class="grid two-col"><section class="card"><div class="card-head"><h3>Nel tuo campo</h3><span>${f?'campo reale':'setup incompleto'}</span></div>${f?`<div class="sensor-box" style="max-width:100%;aspect-ratio:${(f.w/f.h).toFixed(2)}"><span class="sensor-caption">${o.size>=60?(o.size/60).toFixed(2)+'°':o.size+'′'} / ${f.w.toFixed(2)}° × ${f.h.toFixed(2)}°</span></div><p style="font-size:9px;color:#777">${suitability(o)} · ${o.size>Math.max(f.w,f.h)*60?'mosaico o dettaglio':'rappresentazione proporzionale schematica'}</p>`:'<p style="font-size:10px;color:#777">Inserisci fotocamera e sensore in Setup per calcolare la proporzione esatta nel campo.</p>'}<div class="seasonbar" style="--month:${((new Date().getMonth()+.5)/12*100)}%"></div><div class="season-labels"><span>GEN</span><span>APR</span><span>LUG</span><span>OTT</span><span>DIC</span></div><p style="font-size:9px;color:#777">Finestra stagionale indicativa: ${monthName(o.season[0])} – ${monthName(o.season[1])} · ${isSeason(o)?'in stagione ora':'fuori dalla finestra principale'}.</p></section><section class="card"><div class="card-head"><h3>Impostazione</h3><span>stima per orientarsi</span></div><div class="activity"><i>◉</i><span>Filtro consigliato</span><b style="margin-left:auto">${esc(o.filter)}</b></div><div class="activity"><i>◷</i><span>Integrazione indicativa</span><b style="margin-left:auto">${o.hours} h</b></div><div class="activity"><i>☾</i><span>Compatibilità lunare</span><b style="margin-left:auto">${esc(o.moon)}</b></div><div class="activity"><i>⌖</i><span>Altezza massima geometrica</span><b style="margin-left:auto">${alt.toFixed(0)}°</b></div><div class="notice" style="margin-top:12px">Ore, filtro e compatibilità lunare sono orientamenti editoriali, non previsioni di risultato. La stima va verificata su cielo, camera, seeing e obiettivo di elaborazione.</div></section></div><section class="detail-section"><h3>SCIENZA</h3><p style="font-size:11px;line-height:1.7;color:#62645e">${esc(o.science)}</p></section><div class="story-grid"><article class="story"><h3>Storia del catalogo</h3><p>${esc(o.culture)}</p></article><article class="story"><h3>Un dettaglio da cercare</h3><p>${esc(o.story)}</p></article></div><section class="detail-section"><h3>DAL TUO SETUP · ${esc(site.name)}</h3><p style="font-size:10px;color:#656760">Coordinate del soggetto: RA ${o.ra.toFixed(4)}° · Dec ${o.dec>=0?'+':''}${o.dec.toFixed(4)}°. Altezza massima geometrica ${alt.toFixed(0)}°; valore senza rifrazione, ostacoli locali o margine dall’orizzonte. La dimensione è catalografica e può variare secondo la banda e la definizione adottata.</p></section><div class="inline-actions"><button class="button" id="save-target">${saved?'✓ Nella tua collezione':'Aggiungi alla collezione'}</button><button class="button light" id="make-project">Crea progetto</button><a class="button light" target="_blank" rel="noreferrer" href="https://simbad.cds.unistra.fr/simbad/sim-id?Ident=${encodeURIComponent(o.id)}">Apri SIMBAD ↗</a></div></div>`;$('#detail-dialog').showModal();$('[data-close]')?.addEventListener('click',()=>$('#detail-dialog').close());$('#save-target').onclick=()=>{if(!state.collection.includes(id))state.collection.push(id);else state.collection=state.collection.filter(x=>x!==id);save();openDetail(id);toast(state.collection.includes(id)?'Aggiunto alla collezione':'Rimosso dalla collezione')};$('#make-project').onclick=()=>{let name=`${o.id} · ${o.name}`;$('#detail-dialog').close();openProjectForm({target:o.id,name,hours:o.hours})}}
function actions(a){if(a==='add-gear')openGearForm();if(a==='add-site')openSiteForm();if(a==='new-project')openProjectForm();if(a==='refresh-weather'){weatherCache=null;loadWeather(true)}if(a==='save-sky')saveSky();if(a==='reset-check'){ $$('[data-check]').forEach(c=>{c.checked=false;localStorage.removeItem('check-'+c.dataset.check)})}}
function modal(title,body){const d=$('#modal-dialog');d.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:start;margin-bottom:18px"><div><p class="eyebrow"><span>OURSKY</span> CONFIGURAZIONE</p><h2 style="font:400 29px var(--serif);margin:0">${title}</h2></div><button class="close-modal" style="border:0;background:none;font-size:21px">×</button></div>${body}`;d.showModal();$('.close-modal',d).onclick=()=>d.close();return d}
function openGearForm(){const d=modal('Aggiungi componente',`<form id="gear-form"><div class="form-grid"><div class="field"><label>Tipo</label><select name="kind" id="gear-kind"><option value="Telescope">Telescopio / ottica</option><option value="Camera">Camera</option><option value="Filter">Filtro</option><option value="Mount">Montatura</option><option value="Accessory">Accessori</option></select></div><div class="field"><label>Marca e modello esatto</label><input name="name" required placeholder="es. ZWO ASI533MC Pro"></div><div class="field telescope-field"><label>Apertura (mm)</label><input name="aperture" type="number" step="1" placeholder="70"></div><div class="field telescope-field"><label>Lunghezza focale nativa (mm)</label><input name="focal" type="number" step="1" placeholder="350"></div><div class="field camera-field" style="display:none"><label>Larghezza sensore (mm)</label><input name="width" type="number" step="0.01" placeholder="23.5"></div><div class="field camera-field" style="display:none"><label>Altezza sensore (mm)</label><input name="height" type="number" step="0.01" placeholder="15.7"></div><div class="field camera-field" style="display:none"><label>Pixel pitch (μm)</label><input name="pixel" type="number" step="0.01" placeholder="3.76"></div><div class="field camera-field" style="display:none"><label>Pixel sensore (opzionale)</label><input name="resolution" placeholder="3008 × 3008"></div><div class="field telescope-field"><label>Riduttore / Barlow (×)</label><input name="factor" type="number" step="0.01" value="1" placeholder="0.8"></div><div class="field"><label>Nota / specifica</label><input name="note" placeholder="es. 1.25″ · dual-band Ha/O III"></div><div class="field full"><div class="notice">Il catalogo modelli completo è in costruzione. Inserisci le specifiche verificate dal produttore; il calcolo FOV usa i numeri, non il nome del modello.</div></div></div><div class="form-foot"><button type="button" class="button light close-modal">Annulla</button><button class="button">Salva componente</button></div></form>`);const kind=$('#gear-kind',d);kind.onchange=()=>{const cam=kind.value==='Camera';$$('.camera-field',d).forEach(x=>x.style.display=cam?'flex':'none');$$('.telescope-field',d).forEach(x=>x.style.display=cam?'none':'flex')};$('#gear-form',d).onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),g={id:crypto.randomUUID(),kind:fd.get('kind'),name:fd.get('name').trim()};['aperture','focal','width','height','pixel','factor','resolution','note'].forEach(k=>{let v=fd.get(k);if(v)g[k]=['aperture','focal','width','height','pixel','factor'].includes(k)?Number(v):v});state.gear.push(g);save();d.close();render();toast('Componente aggiunto al setup')};$$('.close-modal',d).forEach(x=>x.onclick=()=>d.close())}
function openSiteForm(){const d=modal('Aggiungi località',`<form id="site-form"><div class="field"><label>Nome del sito</label><input name="name" required placeholder="Casa, montagna, campo…"></div><div class="field" style="margin-top:11px"><label>Cerca indirizzo o luogo</label><div style="display:flex;gap:7px"><input id="geo-query" placeholder="Comune o indirizzo" style="flex:1"><button type="button" class="button light small" id="geo-search">Cerca</button></div><div id="geo-results" style="font-size:10px;color:#777;margin-top:6px"></div></div><div class="form-grid" style="margin-top:11px"><div class="field"><label>Latitudine</label><input name="lat" id="site-lat" type="number" step="0.00001" value="${(state.sites[0]||defaultSite).lat}" required></div><div class="field"><label>Longitudine</label><input name="lon" id="site-lon" type="number" step="0.00001" value="${(state.sites[0]||defaultSite).lon}" required></div><div class="field full"><div class="notice">Ricerca posizione tramite Nominatim / OpenStreetMap. Verifica il pin prima del salvataggio. Elevazione da inserire manualmente nella prima versione.</div></div></div><div class="form-foot"><button type="button" class="button light close-modal">Annulla</button><button class="button">Salva località</button></div></form>`);$('#geo-search',d).onclick=async()=>{let q=$('#geo-query',d).value.trim();if(!q)return;$('#geo-results',d).textContent='Ricerca…';try{let res=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=5&q=${encodeURIComponent(q)}`,{headers:{'Accept-Language':'it'}});let a=await res.json();$('#geo-results',d).innerHTML=a.map(x=>`<button type="button" class="text-button geo-hit" data-lat="${x.lat}" data-lon="${x.lon}" style="display:block;text-align:left">${esc(x.display_name)}</button>`).join('')||'Nessun risultato';$$('.geo-hit',d).forEach(b=>b.onclick=()=>{$('#site-lat',d).value=b.dataset.lat;$('#site-lon',d).value=b.dataset.lon;$('#geo-results',d).textContent='Coordinate selezionate'})}catch{$('#geo-results',d).textContent='Servizio non raggiungibile. Inserisci le coordinate manualmente.'}};$('#site-form',d).onsubmit=e=>{e.preventDefault();let fd=new FormData(e.target),s={id:crypto.randomUUID(),name:fd.get('name'),lat:+fd.get('lat'),lon:+fd.get('lon'),elev:null,bortle:null,sqm:null};state.sites.push(s);state.activeSite=s.id;save();d.close();go('sites')};$$('.close-modal',d).forEach(x=>x.onclick=()=>d.close())}
function openProjectForm(prefill={}){const d=modal('Nuovo progetto',`<form id="project-form"><div class="form-grid"><div class="field full"><label>Nome del progetto</label><input name="name" required value="${esc(prefill.name||'')}" placeholder="es. Nebulose estive con dual-band"></div><div class="field"><label>Soggetto / catalogo</label><select name="target"><option value="">Seleziona un soggetto</option>${catalog.map(o=>`<option value="${o.id}" ${prefill.target===o.id?'selected':''}>${o.id} · ${esc(o.name)}</option>`).join('')}</select></div><div class="field"><label>Setup</label><select name="gear">${state.gear.filter(g=>g.kind==='Telescope').map(g=>`<option>${esc(g.name)}</option>`).join('')||'<option>Da configurare</option>'}</select></div><div class="field"><label>Località</label><select name="site">${state.sites.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Integrazione obiettivo (ore)</label><input name="hours" type="number" min="1" max="100" value="${prefill.hours||4}"></div><div class="field"><label>Luna massima accettata (%)</label><input name="moon" type="number" min="0" max="100" value="35"></div><div class="field"><label>Altezza minima target (°)</label><input name="alt" type="number" min="0" max="90" value="30"></div><div class="field"><label>Nuvolosità massima (%)</label><input name="cloud" type="number" min="0" max="100" value="25"></div><div class="field full"><label>Disponibilità / note</label><input name="notes" placeholder="es. venerdì e sabato, da novembre a febbraio"></div></div><div class="form-foot"><button type="button" class="button light close-modal">Annulla</button><button class="button">Crea progetto</button></div></form>`);$('#project-form',d).onsubmit=e=>{e.preventDefault();let fd=new FormData(e.target),site=state.sites.find(s=>s.id===fd.get('site'))||defaultSite;let p={id:crypto.randomUUID(),name:fd.get('name'),target:fd.get('target'),setupName:fd.get('gear'),site:fd.get('site'),siteName:site.name,hours:+fd.get('hours')||4,moon:+fd.get('moon'),alt:+fd.get('alt'),cloud:+fd.get('cloud'),notes:fd.get('notes'),created:new Date().toISOString(),progress:12};state.projects.unshift(p);save();d.close();go('projects');toast('Progetto creato')};$$('.close-modal',d).forEach(x=>x.onclick=()=>d.close())}
function openProject(id){let p=state.projects.find(x=>x.id===id);if(!p)return;let o=catalog.find(x=>x.id===p.target);modal(p.name,`<div class="grid two-col"><section><div class="label-tag">SOGGETTO</div><h3 style="font:400 22px var(--serif);margin:7px 0">${esc(o?.name||p.target||'Da selezionare')}</h3><p style="font-size:10px;color:#777">${esc(o?.const||'')} · ${esc(p.setupName)}</p><div class="activity"><i>◷</i><span>Integrazione desiderata</span><b style="margin-left:auto">${p.hours} ore</b></div><div class="activity"><i>☾</i><span>Luna massima</span><b style="margin-left:auto">${p.moon}%</b></div><div class="activity"><i>⌖</i><span>Altezza minima</span><b style="margin-left:auto">${p.alt}°</b></div><div class="activity"><i>☁</i><span>Nuvolosità massima</span><b style="margin-left:auto">${p.cloud}%</b></div></section><section><div class="label-tag">CHECKLIST DEL PROGETTO</div>${[['Setup verificato','pc1'],['Location confermata','pc2'],['Previsioni controllate','pc3'],['Sequenza acquisizione pronta','pc4']].map(([l,k])=>`<label class="switch-row"><span>${l}</span><input type="checkbox" data-project-check="${id}-${k}"></label>`).join('')}<p style="font-size:9px;color:#777;line-height:1.5;margin-top:12px">${esc(p.notes||'Nessuna nota')}</p></section></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:19px"><button class="text-button" id="delete-project">Elimina progetto</button><div class="inline-actions"><button class="button light" id="export-project">Esporta scheda</button><button class="button" id="detail-target">Scheda soggetto ↗</button></div></div>`);const d=$('#modal-dialog');$$('[data-project-check]',d).forEach(c=>{c.checked=!!localStorage.getItem('check-'+c.dataset.projectCheck);c.onchange=()=>localStorage.setItem('check-'+c.dataset.projectCheck,c.checked?'1':'')});$('#delete-project',d).onclick=()=>{state.projects=state.projects.filter(x=>x.id!==id);save();d.close();render();toast('Progetto eliminato')};$('#export-project',d).onclick=()=>{const text=`${p.name}\nSoggetto: ${o?.name||p.target}\nRA: ${o?.ra}°\nDec: ${o?.dec}°\nIntegrazione: ${p.hours} h\nSetup: ${p.setupName}\nLocalità: ${p.siteName}`;navigator.clipboard?.writeText(text).then(()=>toast('Scheda copiata negli appunti')).catch(()=>toast(text))};$('#detail-target',d).onclick=()=>{d.close();o?openDetail(o.id):go('catalog')}}
function saveSky(){let s=state.sites.find(x=>x.id===state.activeSite);if(!s)return;s.bortle=$('#bortle-edit')?.value||null;s.sqm=$('#sqm-edit')?.value||null;save();if(page==='sites')render();toast('Qualità cielo salvata')}
async function loadWeather(force=false){const s=state.sites.find(x=>x.id===state.activeSite)||defaultSite;let target=page==='home'?$('#weather-snippet'):$('#weather-full');if(!target)return;if(weatherCache&&!force&&weatherCache.site===s.id){target.innerHTML=weatherHTML(weatherCache.data,page==='home');return}try{let url=`https://api.open-meteo.com/v1/forecast?latitude=${s.lat}&longitude=${s.lon}&daily=weather_code,temperature_2m_min,temperature_2m_max,precipitation_probability_max,sunrise,sunset&hourly=cloud_cover,relative_humidity_2m,wind_speed_10m&forecast_days=7&timezone=auto`;let r=await fetch(url);if(!r.ok)throw new Error();let data=await r.json();weatherCache={site:s.id,data};target=page==='home'?$('#weather-snippet'):$('#weather-full');if(target)target.innerHTML=weatherHTML(data,page==='home')}catch{target=page==='home'?$('#weather-snippet'):$('#weather-full');if(target)target.innerHTML='<div class="empty">Previsioni non raggiungibili ora. Controlla la connessione o apri Open-Meteo.</div>'}}
function weatherHTML(d,compact){const i=0,code=d.daily.weather_code[i],label=wx(code);return compact?`<div style="display:flex;align-items:center;gap:14px"><strong class="weather-big">${Math.round(d.daily.temperature_2m_min[i])}° / ${Math.round(d.daily.temperature_2m_max[i])}°</strong><div><div style="font-size:11px">${label}</div><div style="font-size:9px;color:#85877f;margin-top:5px">Nuvole ora ${d.hourly.cloud_cover[new Date().getHours()]??'—'}% · pioggia max ${d.daily.precipitation_probability_max[i]}%</div></div></div><div class="weather-detail"><span>ALBA ${time(d.daily.sunrise[i])}</span><span>TRAMONTO ${time(d.daily.sunset[i])}</span><span>VENTO ${Math.round(d.hourly.wind_speed_10m[new Date().getHours()]||0)} km/h</span></div>`:`<div class="grid three-col">${d.daily.time.slice(0,7).map((date,i)=>`<div class="card" style="padding:11px;background:#f7f5ef"><div class="label-tag">${new Date(date+'T12:00').toLocaleDateString('it-IT',{weekday:'short',day:'numeric'})}</div><div style="font:400 18px var(--serif);margin:7px 0">${wx(d.daily.weather_code[i])}</div><div style="font-size:10px">${Math.round(d.daily.temperature_2m_min[i])}° / ${Math.round(d.daily.temperature_2m_max[i])}°</div><div style="font-size:8px;color:#82847c;margin-top:6px">nuvole ora ${i===0?(d.hourly.cloud_cover[new Date().getHours()]??'—'):'—'}% · pioggia ${d.daily.precipitation_probability_max[i]}%</div></div>`).join('')}</div><div class="weather-detail" style="margin-top:10px"><span>ALBA ${time(d.daily.sunrise[0])}</span><span>TRAMONTO ${time(d.daily.sunset[0])}</span><span>FONTE OPEN-METEO · AGGIORNAMENTO LIVE</span></div>`}
function time(x){return x?.slice(11,16)||'—'}function wx(c){return c===0?'Sereno':c<=2?'Poco nuvoloso':c===3?'Nuvoloso':c<50?'Nebbia':c<70?'Pioviggine':c<80?'Pioggia':'Temporale'}
let calendarOffset=0;function shiftMonth(k){calendarOffset+=k;let d=new Date();d.setDate(1);d.setMonth(d.getMonth()+calendarOffset);const date=d;const start=(new Date(date.getFullYear(),date.getMonth(),1).getDay()+6)%7,days=new Date(date.getFullYear(),date.getMonth()+1,0).getDate();$('#calendar-title').textContent=new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric'}).format(date);$('.calendar-grid').innerHTML=['LUN','MAR','MER','GIO','VEN','SAB','DOM'].map(w=>`<div class="day" style="min-height:26px;background:#eeece5;font-size:8px;letter-spacing:.1em">${w}</div>`).join('')+Array.from({length:42},(_,i)=>{let n=i-start+1,ok=n>0&&n<=days,dt=new Date(date.getFullYear(),date.getMonth(),n),obs=catalog.filter(o=>isSeason(o,dt)).sort((a,b)=>b.size-a.size)[0];return `<div class="day ${ok?'':'muted'}">${ok?n:''}<span class="moon">${ok?moonEmoji(dt):''}</span>${ok&&n%4===0&&obs?`<span class="event-dot">${obs.id} · ${esc(obs.name)}</span>`:''}</div>`}).join('')}
$$('.rail-nav button').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));$('#mobile-menu').onclick=()=>$('.rail').classList.toggle('open');$('#about-open').onclick=()=>modal('OurSky',`<p style="font-size:11px;line-height:1.7;color:#666">OurSky unisce scoperta del cielo e pianificazione astrofotografica. Il catalogo NGC/IC usa OpenNGC (CC BY-SA 4.0, attribuzione: Mattia Verga e contributori); la selezione curata integra schede introduttive. Meteo da Open-Meteo; ricerca luoghi via Nominatim/OpenStreetMap; mappa luce via Light Pollution Map. Le integrazioni AstroBin e software di acquisizione richiedono API/permessi e non sono dichiarate attive in questa versione.</p><div class="label-tag">DATI DEL PROFILO SALVATI SU QUESTO DISPOSITIVO</div>`);$('#quick-location').onclick=()=>go('sites');$('#today').textContent=new Intl.DateTimeFormat('it-IT',{weekday:'short',day:'numeric',month:'short'}).format(new Date()).toUpperCase();updateCounts();render();loadOpenNGC();
